def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    # Select whether the repeated stripes run along r-c or r+c.
    def stripe_groups(use_difference):
        groups = {}
        for r, c, color in cells:
            k = c - r if use_difference else c + r
            groups.setdefault(k, []).append(color)
        return groups

    candidates = []
    for use_difference in (True, False):
        groups = stripe_groups(use_difference)
        coherence = sum(len(v) ** 2 for v in groups.values())
        candidates.append((coherence, use_difference, groups))
    _, use_difference, groups = max(candidates, key=lambda x: x[0])

    stripe_colors = {k: colors[0] for k, colors in groups.items()}
    keys = list(stripe_colors)

    # Find the shortest repeating period consistent with the observed stripes.
    period = 1
    for p in range(1, 2 * max(h, w) + 1):
        residues = {}
        valid = True
        for k, color in stripe_colors.items():
            residue = k % p
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            period = p
            break

    pattern = {k % period: color for k, color in stripe_colors.items()}
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            k = c - r if use_difference else c + r
            row.append(pattern.get(k % period, 0))
        out.append(row)
    return out
